// Copyright 2015-2021 Crytek GmbH / Crytek Group. All rights reserved.#include "StdAfx.h"#include "AutoExposure.h"#include "Common/PostProcess/PostProcessUtils.h"#include "Common/RendererResources.h"// The metering histogram's window, in stops relative to mid grey. The C++ twin of// SCENE_METER_HIST_LOG_MIN / _MAX in HDRPostProcess.cfx, and the only place the CPU is allowed to// know it: the value travels to the camera inside SSceneReferredMeterHistogram so that a third// copy cannot drift out of step with these two.static const float kMeterHistogramLogMin = -14.0f;static const float kMeterHistogramLogMax =  18.0f;void GetSampleOffsets_Downscale4x4Bilinear(uint32 width, uint32 height, Vec4 avSampleOffsets[]){	float tU = 1.0f / (float)width;	float tV = 1.0f / (float)height;	// Sample from the 16 surrounding points.  Since bilinear filtering is being used, specific the coordinate	// exactly halfway between the current texel center (k-1.5) and the neighboring texel center (k-0.5)	int index = 0;	for (int y = 0; y < 4; y += 2)	{		for (int x = 0; x < 4; x += 2, index++)		{			avSampleOffsets[index].x = (x - 1.f) * tU;			avSampleOffsets[index].y = (y - 1.f) * tV;			avSampleOffsets[index].z = 0;			avSampleOffsets[index].w = 1;		}	}}void CAutoExposureStage::MeasureLuminance(){	PROFILE_LABEL_SCOPE("MEASURE_LUMINANCE");	int32 curTexture = NUM_HDR_TONEMAP_TEXTURES - 1;	float tU = 1.0f / (3.0f * CRendererResources::s_ptexHDRToneMaps[curTexture]->GetWidth());	float tV = 1.0f / (3.0f * CRendererResources::s_ptexHDRToneMaps[curTexture]->GetHeight());	Vec4 sampleOffsets[16];	uint32 index = 0;	for (int x = -1; x <= 1; x++)	{		for (int y = -1; y <= 1; y++)		{			sampleOffsets[index].x = x * tU;			sampleOffsets[index].y = y * tV;			sampleOffsets[index].z = 0;			sampleOffsets[index].w = 1;			index++;		}	}	CShader* pShader = CShaderMan::s_shHDRPostProcess;	// Initial downsampling	{		if (m_passLuminanceInitial.IsDirty())		{			static CCryNameTSCRC techLumInitial("HDRSampleLumInitial");			m_passLuminanceInitial.SetPrimitiveFlags(CRenderPrimitive::eFlags_ReflectShaderConstants_PS);			m_passLuminanceInitial.SetPrimitiveType(CRenderPrimitive::ePrim_ProceduralTriangle);			m_passLuminanceInitial.SetTechnique(pShader, techLumInitial, 0);			m_passLuminanceInitial.SetRenderTarget(0, CRendererResources::s_ptexHDRToneMaps[curTexture]);			m_passLuminanceInitial.SetState(GS_NODEPTHTEST);			m_passLuminanceInitial.SetFlags(CPrimitiveRenderPass::ePassFlags_RequireVrProjectionConstants);			// Scene-referred pipeline (SceneReferredSpec.md S3): this pass is the EV-defining			// site - GetWorkingLuminance() at HDRPostProcess.cfx:750 is what feeds			// ComputeExposure - and the weights it needs live in the per-view constant buffer,			// which stock CE did not bind here. Without this the meter would keep measuring AP1			// data with Rec.709 weights and every exposure would be quietly wrong on the			// scene-referred path. Off the switch the delta is an exact 0.0, so the pixels are			// unchanged; only the binding appears. Note the two OTHER GetLuminance calls in the			// same shader (:743, :746) read the G-BUFFER and deliberately stay Rec.709.			m_passLuminanceInitial.SetRequirePerViewConstantBuffer(true);			m_passLuminanceInitial.SetTexture(0, m_graphicsPipelineResources.m_pTexHDRTargetScaled[1][0]);			m_passLuminanceInitial.SetTexture(1, m_graphicsPipelineResources.m_pTexSceneNormalsMap);			m_passLuminanceInitial.SetTexture(2, m_graphicsPipelineResources.m_pTexSceneDiffuse);			m_passLuminanceInitial.SetTexture(3, m_graphicsPipelineResources.m_pTexSceneSpecular);			m_passLuminanceInitial.SetSampler(0, EDefaultSamplerStates::LinearClamp);		}		static CCryNameR sampleLumOffsets0Name("SampleLumOffsets0");		static CCryNameR sampleLumOffsets1Name("SampleLumOffsets1");		m_passLuminanceInitial.BeginConstantUpdate();		float s1 = 1.0f / (float)m_graphicsPipelineResources.m_pTexHDRTargetScaled[1][0]->GetWidth();		float t1 = 1.0f / (float)m_graphicsPipelineResources.m_pTexHDRTargetScaled[1][0]->GetHeight();		// Use rotated grid		Vec4 sampleLumOffsets0 = Vec4(s1 * 0.95f, t1 * 0.25f, -s1 * 0.25f, t1 * 0.96f);		Vec4 sampleLumOffsets1 = Vec4(-s1 * 0.96f, -t1 * 0.25f, s1 * 0.25f, -t1 * 0.96f);		m_passLuminanceInitial.SetConstant(sampleLumOffsets0Name, sampleLumOffsets0, eHWSC_Pixel);		m_passLuminanceInitial.SetConstant(sampleLumOffsets1Name, sampleLumOffsets1, eHWSC_Pixel);		m_passLuminanceInitial.Execute();	}	// Iterative downsampling	for (curTexture = curTexture - 1; curTexture >= 0; --curTexture)	{		CFullscreenPass& passLuminanceIteration = m_passLuminanceIteration[curTexture];		if (passLuminanceIteration.IsDirty())		{			uint64 rtMask = 0;			if (!curTexture)				rtMask |= g_HWSR_MaskBit[HWSR_SAMPLE0];			if (curTexture == 1)				rtMask |= g_HWSR_MaskBit[HWSR_SAMPLE1];			static CCryNameTSCRC techLumIterative("HDRSampleLumIterative");			passLuminanceIteration.SetPrimitiveFlags(CRenderPrimitive::eFlags_ReflectShaderConstants_PS);			passLuminanceIteration.SetPrimitiveType(CRenderPrimitive::ePrim_ProceduralTriangle);			passLuminanceIteration.SetTechnique(pShader, techLumIterative, rtMask);			passLuminanceIteration.SetRenderTarget(0, CRendererResources::s_ptexHDRToneMaps[curTexture]);			passLuminanceIteration.SetState(GS_NODEPTHTEST);			passLuminanceIteration.SetTexture(0, CRendererResources::s_ptexHDRToneMaps[curTexture + 1]);			passLuminanceIteration.SetSampler(0, EDefaultSamplerStates::LinearClamp);		}		static CCryNameR param1Name("SampleOffsets");		passLuminanceIteration.BeginConstantUpdate();		GetSampleOffsets_Downscale4x4Bilinear(CRendererResources::s_ptexHDRToneMaps[curTexture + 1]->GetWidth(), CRendererResources::s_ptexHDRToneMaps[curTexture + 1]->GetHeight(), sampleOffsets);		passLuminanceIteration.SetConstantArray(param1Name, sampleOffsets, 4, eHWSC_Pixel);		passLuminanceIteration.Execute();	}	GetDeviceObjectFactory().GetCoreCommandList().GetCopyInterface()->Copy(		CRendererResources::s_ptexHDRToneMaps[0]->GetDevTexture(),		m_graphicsPipelineResources.m_pTexHDRMeasuredLuminance[gcpRendD3D->RT_GetCurrGpuID()]->GetDevTexture()	);}void CAutoExposureStage::AdjustExposure(){	PROFILE_LABEL_SCOPE("EYEADAPTATION");	CD3D9Renderer* pRenderer = gcpRendD3D;	// Swap current & last luminance	const int lumMask = (int32)(sizeof(CRendererResources::s_ptexHDRAdaptedLuminanceCur) / sizeof(CRendererResources::s_ptexHDRAdaptedLuminanceCur[0])) - 1;	const int32 numTextures = (int32)max(min(gRenDev->GetActiveGPUCount(), (uint32)(sizeof(CRendererResources::s_ptexHDRAdaptedLuminanceCur) / sizeof(CRendererResources::s_ptexHDRAdaptedLuminanceCur[0]))), 1u);	CRendererResources::s_nCurLumTextureIndex++;	CTexture* pTexPrev = CRendererResources::s_ptexHDRAdaptedLuminanceCur[(CRendererResources::s_nCurLumTextureIndex - numTextures) & lumMask];	CTexture* pTexCur = CRendererResources::s_ptexHDRAdaptedLuminanceCur[CRendererResources::s_nCurLumTextureIndex & lumMask];	CRendererResources::s_ptexCurLumTexture = pTexCur;	assert(pTexCur);	CShader* pShader = CShaderMan::s_shHDRPostProcess;	if (m_passAutoExposure.IsDirty(pTexCur->GetTextureID(), pTexPrev->GetTextureID()))	{		static CCryNameTSCRC techAdaptedLum("HDRCalculateAdaptedLum");		m_passAutoExposure.SetPrimitiveFlags(CRenderPrimitive::eFlags_ReflectShaderConstants_PS);		m_passAutoExposure.SetPrimitiveType(CRenderPrimitive::ePrim_ProceduralTriangle);		m_passAutoExposure.SetTechnique(pShader, techAdaptedLum, 0);		m_passAutoExposure.SetRenderTarget(0, pTexCur);		m_passAutoExposure.SetState(GS_NODEPTHTEST);		m_passAutoExposure.SetTexture(0, pTexPrev);		m_passAutoExposure.SetTexture(1, CRendererResources::s_ptexHDRToneMaps[0]);	}	static CCryNameR param0Name("ElapsedTime");	m_passAutoExposure.BeginConstantUpdate();	Vec4 param0(iTimer->GetFrameTime() * numTextures, 1, 1, 0);	if (!RenderView()->GetCamera(CCamera::eEye_Left).IsJustActivated() && pRenderer->m_nDisableTemporalEffects == 0)	{		param0[1] = 1.0f - expf(-CRenderer::CV_r_HDREyeAdaptationSpeed * param0[0]);		param0[2] = 1.0f - expf(-CRenderer::CV_r_HDRRangeAdaptationSpeed * param0[0]);	}	m_passAutoExposure.SetConstant(param0Name, param0, eHWSC_Pixel);	m_passAutoExposure.Execute();}// Scene-referred AUTO metering: the CPU half of the camera's exposure loop// (SceneReferredSpec.md D2/D7, decisions/s1-auto-mode.md part 1, approach A).//// Passes 1 and 2 above already produce exactly what a camera's incident meter wants: a 1x1// R16G16F whose .y is the geometric-mean illuminance estimate in engine units, albedo divided// out. Pass 3 (the temporal adaptation) and both ComputeExposure branches are BYPASSED on this// path - not stopped: screen-space reflections bind m_pTexHDRMeasuredLuminance and the film// grain binds s_ptexCurLumTexture, so the stage keeps running and only its exposure stops being// consumed. Smoothing, limits, lock and compensation move to the camera, in EV, where a camera's// controls live.//// s_ptexHDRToneMaps[0] is created with FT_STAGE_READBACK (RendererResources.cpp), so it already// owns a PERSISTENT staging resource: no copy pass and no texture of our own are needed, unlike// CBloomStage::UpdateDiffractionSourceReadback, whose two-phase shape this otherwise follows// exactly. Cost is four bytes and one fence per frame. The blocking one-shot form// DownloadToStagingResource(sub, hook) - what r_HDRDebug 1 uses - is a full pipeline stall and is// not acceptable per frame.//// The pre-exposure is divided out HERE rather than in the camera. The camera would otherwise have// to keep a history of the exposures it published and guess which frame the sample came from; the// stage knows exactly, because it recorded the value when it issued the download. Getting that// wrong turns the meter into a two-frame-delayed feedback loop, which oscillates.void CAutoExposureStage::UpdateSceneReferredMeterReadback(){	CD3D9Renderer* const pRenderer = gcpRendD3D;	// Cube-map generation renders at unity exposure and is not a view anybody meters.	const bool bCubemapGen = (m_graphicsPipeline.GetRenderFlags() & SHDF_CUBEMAPGEN) != 0;	if (!CRendererResources::IsSceneReferredStage(2) || bCubemapGen)	{		// Leaving the path with a download in flight is fine - the staging resource belongs to the		// texture, not to us, and nothing is freed here. Only the reported value is retired, so		// the camera cannot keep metering off a sample from before the switch was flipped.		m_bMeterReadbackIssued = false;		m_bMeterReadbackStalled = false;		RetireSceneReferredMeter();		return;	}	// WHICH meter is running this frame. The histogram (default) is the one the camera acts on;	// r_SceneReferredMeterHistogram 0 falls back to the shipped whole-frame log-mean, which stays	// in the tree as the A/B reference and as the fallback if the compute pass ever misbehaves	// (decisions/s8-metering.md approach B). Exactly one of the two publishes at a time, so the	// camera can tell which number it is being handed.	const bool bHistogram = m_bMeterHistogramValid;	CTexture* pMeterTex = bHistogram ? m_pTexMeterHistogram.get() : CRendererResources::s_ptexHDRToneMaps[0];	if (!CTexture::IsTextureExist(pMeterTex))		return;	// A flip between the two while a download is in flight retires the sample rather than	// decoding it with the wrong reader. One frame of holding, at a switch nobody flips in play.	if (m_bMeterReadbackIssued && m_bMeterIssuedHistogram != bHistogram)	{		m_bMeterReadbackIssued = false;		m_bMeterReadbackStalled = false;		RetireSceneReferredMeter();	}	CDeviceTexture* pDevTex = pMeterTex->GetDevTexture();	if (pDevTex == nullptr)		return;	const float fNow = gEnv->pTimer->GetAsyncCurTime();	if (m_bMeterReadbackIssued)	{		// Not signalled yet: come back next frame. Never block.		if (!pDevTex->AccessCurrStagingResource(0, false))		{			if ((fNow - m_fMeterIssuedTime) > 5.0f && !m_bMeterReadbackStalled)			{				m_bMeterReadbackStalled = true;				CryLogAlways("[SceneReferred] the exposure meter's staging download has not signalled in 5 s - AUTO is holding its last EV");			}			return;		}		m_bMeterReadbackStalled = false;		if (m_bMeterIssuedHistogram)		{			// 64 x uint32 in the single row of a 64x1 R32-typeless target. The texture's ETEX_Format			// says R32F, which is a lie the engine's format list forces on us (it has no uint			// entry); the UAV the shader wrote through is a typed R32_UINT view of the same			// typeless resource, so the BYTES are the counts and only the reinterpretation is new.			SSceneReferredMeterHistogram hist;			ZeroStruct(hist);			// The two sky accumulators sit after the bins in the same row (decisions/			// s8-metering-sky.md): the sky texel count (x256, unmasked) and the sky weight that			// actually went into the bins (masked and down-weighted).			float fSkyCount = 0.0f, fSkyWeight = 0.0f;			const auto readbackBins = [&hist, &fSkyCount, &fSkyWeight](void* pData, uint32 rowPitch, uint32 slicePitch) -> bool			{				const uint32* pBins = static_cast<const uint32*>(pData);				for (int i = 0; i < SSceneReferredMeterHistogram::kBinCount; ++i)					hist.bins[i] = (float)pBins[i];				fSkyCount  = (float)pBins[SSceneReferredMeterHistogram::kBinCount + 0];				fSkyWeight = (float)pBins[SSceneReferredMeterHistogram::kBinCount + 1];				return true;			};			pDevTex->AccessCurrStagingResource(0, false, readbackBins);			m_bMeterReadbackIssued = false;			float fTotal = 0.0f;			for (int i = 0; i < SSceneReferredMeterHistogram::kBinCount; ++i)				fTotal += hist.bins[i];			// 256.0f is SCENE_METER_HIST_WEIGHT_Q. skyFraction is of the FRAME (what the camera			// sees), skyMeterShare is of the METER (what the camera acts on); the gap between the			// two is the down-weight doing its job, and the overlay prints both.			hist.skyFraction   = (m_fMeterIssuedTexels > 0.0f) ? clamp_tpl(fSkyCount / (256.0f * m_fMeterIssuedTexels), 0.0f, 1.0f) : 0.0f;			hist.skyMeterShare = (fTotal > 0.0f) ? clamp_tpl(fSkyWeight / fTotal, 0.0f, 1.0f) : 0.0f;			hist.skyWeight     = m_fMeterIssuedSkyWeight;			// The window has to travel with the bins: it is a compile-time constant in the shader,			// but the camera must not have to keep a second copy of it in step by hand.			hist.totalWeight = fTotal;			hist.exposureAtCapture = max(m_fMeterIssuedExposure, 1e-12f);			hist.logMinStops = kMeterHistogramLogMin;			hist.logMaxStops = kMeterHistogramLogMax;			hist.meteringMode = m_nMeterIssuedMode;			// Zero total means the dispatch found nothing to bin (a frame of pure NaN, or a			// resolution of zero). sampleId stays 0 and the camera reads that as "no measurement,			// hold the last EV" - the same rule the scalar meter has always had.			hist.sampleId = (fTotal > 0.0f) ? ++m_nMeterSampleId : 0;			pRenderer->m_sceneReferredMeterHistogram = hist;			// The scalar meter is not being computed on this path; publishing a stale value would			// let the camera fall back to it silently.			pRenderer->m_fSceneReferredMeteredIlluminance = 0.0f;			pRenderer->m_fSceneReferredMeterRaw = 0.0f;			pRenderer->m_fSceneReferredMeterExposure = hist.exposureAtCapture;			pRenderer->m_bSceneReferredMeterRejected = (fTotal <= 0.0f);		}		else		{		float fIlluminance = 0.0f;		const auto readbackData = [&fIlluminance](void* pData, uint32 rowPitch, uint32 slicePitch) -> bool		{			// R16G16F: .x is the geometric-mean luminance, .y the illuminance estimate. .y is the			// incident-meter quantity and the one the EV path has always used.			const CryHalf* pDataHalf = static_cast<const CryHalf*>(pData);			fIlluminance = CryConvertHalfToFloat(pDataHalf[1]);			return true;		};		pDevTex->AccessCurrStagingResource(0, false, readbackData);		m_bMeterReadbackIssued = false;		// Divide out the exposure that was applied to the frame this sample was measured on, and		// reject anything the measure pass could not produce a sane number for (its own isfinite		// filter covers NaNs in the source, not a zero illuminance in a black frame).		const float fExposureAtCapture = max(m_fMeterIssuedExposure, 1e-12f);		const float fAbsolute = fIlluminance / fExposureAtCapture;		// The plausibility window, in ABSOLUTE engine units (1.0 = 10 000 lux here, the same		// LIGHT_UNIT_SCALE the luminance side uses). The lower bound is well below a moonless		// overcast night (~1e-3 lux = 1e-7) and the upper bound well above the sun's own		// illuminance at zenith (~120 000 lux = 12); anything outside is not a scene, it is the		// meter having lost its footing, and the right answer is to HOLD the last EV rather than		// to feed the camera a number that will drive it to a limit. This is the last line of		// defence behind the shader's ceiling, not a substitute for it: a value that merely		// clipped would still be inside the window and would still be acted on, correctly.		const bool bSane = NumberValid(fAbsolute) && fAbsolute > 1e-9f && fAbsolute < 1e4f;		pRenderer->m_fSceneReferredMeteredIlluminance = bSane ? fAbsolute : 0.0f;		pRenderer->m_fSceneReferredMeterRaw = fIlluminance;		pRenderer->m_fSceneReferredMeterExposure = fExposureAtCapture;		pRenderer->m_bSceneReferredMeterRejected = !bSane;		// Same argument the other way round: on the log-mean path there is no live histogram, and		// a stale one would keep the camera on the band it computed before the flip.		ZeroStruct(pRenderer->m_sceneReferredMeterHistogram);		}	}	if (!m_bMeterReadbackIssued)	{		// Every frame, unlike the diffraction debug readback: this closes an exposure loop, and a		// one-second cadence would be visible as steps.		pDevTex->DownloadToStagingResource(0);		m_bMeterReadbackIssued = true;		m_bMeterIssuedHistogram = bHistogram;		m_fMeterIssuedExposure = pRenderer->GetSceneReferredExposure();		m_fMeterIssuedTime = fNow;		m_fMeterIssuedSkyWeight = m_fMeterSkyWeightUsed;		{			const CTexture* pSource = m_graphicsPipelineResources.m_pTexHDRTargetScaled[1][0];			m_fMeterIssuedTexels = CTexture::IsTextureExist(pSource)			                       ? (float)(pSource->GetWidth() * pSource->GetHeight())			                       : 0.0f;		}	}}// The retirement rule, in one place. Every published meter number goes to its "no measurement"// value, which the camera reads as "hold the last EV" rather than as a scene that just went black.void CAutoExposureStage::RetireSceneReferredMeter(){	CD3D9Renderer* const pRenderer = gcpRendD3D;	pRenderer->m_fSceneReferredMeteredIlluminance = 0.0f;	pRenderer->m_fSceneReferredMeterRaw = 0.0f;	pRenderer->m_fSceneReferredMeterExposure = 1.0f;	pRenderer->m_bSceneReferredMeterRejected = false;	ZeroStruct(pRenderer->m_sceneReferredMeterHistogram);}// The 64x1 accumulation target (decisions/s8-metering.md approach A, "the readback is the code we// already wrote").//// It is a TEXTURE and not a CGpuBuffer for one concrete reason: DownloadToStagingResource lives on// CDeviceTexture and has no CDeviceBuffer twin anywhere in this tree, so a buffer histogram would// need a copy pass and a staging texture of its own. 64 uints is 256 bytes, one fence a frame.//// The format is the awkward part. CRYENGINE's ETEX_Format list has no unsigned-integer entry at// all, and InterlockedAdd needs an R32_UINT typed UAV. The way through is the one the linear-depth// fixup target already takes (GraphicsPipeline.cpp, m_pTexLinearDepthFixupUAV): create the texture// as eTF_R32F with FT_USAGE_UAV_RWTEXTURE, which makes the underlying resource R32_TYPELESS, then// build a DXGI_FORMAT_R32_UINT view of it by hand. The declared texture format is then a polite// fiction that nothing reads - the shader writes uints and the CPU decodes uints.bool CAutoExposureStage::EnsureMeterHistogramTexture(){	if (CTexture::IsTextureExist(m_pTexMeterHistogram))	{		// The texture object is alive, but the DEVICE texture under it may not be the one the		// cached UAV handle was created from: a level change frees render resources and the pool		// re-creates the device texture under the same CTexture. The handle is an index into the		// device texture's own view container, so carrying it across that swap indexes past the		// end of a freshly created (predefined-views-only) container, and LookupUAV then hands		// ClearUAV whatever lies past the vector. Re-derive it whenever the owner moves; on the		// common path this is one pointer compare.		CDeviceTexture* pDevTex = m_pTexMeterHistogram->GetDevTexture();		if (pDevTex != m_pMeterHistogramUAVOwner)		{			const SResourceView typedUAV = SResourceView::UnorderedAccessView(DXGI_FORMAT_R32_UINT, 0, -1, 0,			                                                                  SResourceView::eUAV_ReadWrite);			m_meterHistogramUAV = pDevTex->GetOrCreateResourceViewHandle(typedUAV);			m_pMeterHistogramUAVOwner = pDevTex;		}		return true;	}	m_pMeterHistogramUAVOwner = nullptr;	const uint32 flags = FT_NOMIPS | FT_DONT_STREAM | FT_USAGE_RENDERTARGET	                     | FT_USAGE_UNORDERED_ACCESS | FT_USAGE_UAV_RWTEXTURE | FT_STAGE_READBACK;	const std::string id = m_graphicsPipeline.GetUniqueIdentifierName();	// 64 bins plus the two sky accumulators, one row (decisions/s8-metering-sky.md).	m_pTexMeterHistogram = CTexture::GetOrCreateRenderTarget(("$SceneReferredMeterHistogram" + id).c_str(),	                                                         SSceneReferredMeterHistogram::kColumnCount, 1,	                                                         Clr_Transparent, eTT_2D, flags, eTF_R32F);	if (!CTexture::IsTextureExist(m_pTexMeterHistogram) || m_pTexMeterHistogram->GetDevTexture() == nullptr)	{		m_pTexMeterHistogram.reset();		if (!m_bMeterHistogramFailureLogged)		{			m_bMeterHistogramFailureLogged = true;			CryLogAlways("[SceneReferred] the metering histogram target could not be created - AUTO falls back to the log-mean meter");		}		return false;	}	m_bMeterHistogramFailureLogged = false;	const SResourceView typedUAV = SResourceView::UnorderedAccessView(DXGI_FORMAT_R32_UINT, 0, -1, 0,	                                                                  SResourceView::eUAV_ReadWrite);	m_meterHistogramUAV = m_pTexMeterHistogram->GetDevTexture()->GetOrCreateResourceViewHandle(typedUAV);	m_pMeterHistogramUAVOwner = m_pTexMeterHistogram->GetDevTexture();	CryLog("[SceneReferred] metering histogram armed: %d bins, %.1f to %.1f stops over mid grey, %.3f stops per bin",	       (int)SSceneReferredMeterHistogram::kBinCount, kMeterHistogramLogMin, kMeterHistogramLogMax,	       (kMeterHistogramLogMax - kMeterHistogramLogMin) / (float)SSceneReferredMeterHistogram::kBinCount);	return true;}// Clear the bins, then bin the frame (decisions/s8-metering.md approach A, steps 1-2).//// The source is m_pTexHDRTargetScaled[1][0] - the SAME quarter-res copy the stock measure pass// reads, taken at the same point in the frame, so the two meters are looking at the same pixels// and the r_SceneReferredMeterHistogram 0/1 A/B means something. It is the copy AFTER the round-3// firefly-knee change (decisions/s8-fp16-writers.md): the knee's asymptote is now the camera's// white rather than a literal 1.0, so a sunlit texel arrives at its real value instead of being// squeezed into the sliver below display white, which is what made the old downsample useless as// a measurement of anything bright.//// Only ever dispatched on the scene-referred path. Off it the pass does not exist as far as the// command list is concerned, which is what keeps the stock pipeline byte-identical.void CAutoExposureStage::ExecuteMeterHistogram(){	m_bMeterHistogramValid = false;	const bool bCubemapGen = (m_graphicsPipeline.GetRenderFlags() & SHDF_CUBEMAPGEN) != 0;	if (!CRendererResources::IsSceneReferredStage(2) || bCubemapGen)		return;	if (CRenderer::CV_r_SceneReferredMeterHistogram == 0)		return;	CTexture* pSource = m_graphicsPipelineResources.m_pTexHDRTargetScaled[1][0];	if (!CTexture::IsTextureExist(pSource))		return;	// The sky classifier: the quarter-res linear depth, same grid as the source, already produced	// this frame by CSceneDepthStage for AO / fog / DOF (decisions/s8-metering-sky.md approach A).	CTexture* pDepth = m_graphicsPipelineResources.m_pTexLinearDepthScaled[1];	if (!CTexture::IsTextureExist(pDepth))		return;	if (!EnsureMeterHistogramTexture())		return;	PROFILE_LABEL_SCOPE("SCENE_REFERRED_METER_HISTOGRAM");	// The camera's metering mode, published on the post-effect bus beside the pre-exposure. Read	// here rather than passed down from ccam so that the mask the accumulation used travels back	// to the camera with the bins - one authority, one frame.	float fMode = 0.0f;	float fSkyWeight = 1.0f;	if (CPostEffectsMgr* pPostMgr = PostEffectMgr())	{		fMode = pPostMgr->GetByNameF("Global_User_MeterMode");		fSkyWeight = pPostMgr->GetByNameF("Global_User_MeterSkyWeight");	}	const uint32 nMode = (uint32)clamp_tpl((int)(fMode + 0.5f), 0, 2);	fSkyWeight = clamp_tpl(fSkyWeight, 0.0f, 1.0f);	const int width = pSource->GetWidth();	const int height = pSource->GetHeight();	// Both are width_r4 x height_r4 by construction (GraphicsPipeline.cpp), so the depth texel and	// the source texel are the same texel. If that ever stops being true the classification would	// be misaligned along the horizon; say so once and meter with the sky at full weight rather	// than with a wrong mask.	if (pDepth->GetWidth() != width || pDepth->GetHeight() != height)	{		if (!m_bMeterSkyDepthMismatchLogged)		{			m_bMeterSkyDepthMismatchLogged = true;			CryLogAlways("[SceneReferred] metering: quarter-res depth is %dx%d but the meter source is %dx%d - Sky Weight is ignored",			             pDepth->GetWidth(), pDepth->GetHeight(), width, height);		}		fSkyWeight = 1.0f;	}	{		// The bins are accumulated with InterlockedAdd, so they have to start at zero every frame.		// ClearUAV on the typed view, not a render-target clear: the RTV would be R32_FLOAT and		// would write float zeroes, which happen to be the same bits but by accident rather than		// by contract.		CDeviceCommandListRef commandList = GetDeviceObjectFactory().GetCoreCommandList();		const ColorI cClear(0, 0, 0, 0);		// The lookup is bounds-asserted only in Debug, so the null test is the real guard: a view		// that could not be created leaves the bins uncleared, which is a wrong measurement for		// one frame and not a dereference of whatever the index landed on.		D3DUAV* const pUAV = m_pTexMeterHistogram->GetDevTexture()->LookupUAV(m_meterHistogramUAV);		if (pUAV == nullptr)			return;		commandList.GetComputeInterface()->ClearUAV(pUAV, cClear);	}	CComputeRenderPass& pass = m_passMeterHistogram;	// The dirty key has to name the DEVICE textures, not just the texture IDs.	//	// A level load - and a scene-referred format rebuild - gives the same CTexture object a brand	// new device texture without changing its texture ID. The ID-only key therefore said "not	// dirty", SetOutputUAV() was not re-issued, and the CComputeRenderPass kept the previous	// ResourceViewHandle: an INDEX into the OLD device texture's view container, handed to the	// driver against the new one. Whether it bit depended on whether GetOrCreateResourceViewHandle	// happened to hand back the same index on the new device texture, which is what made the	// resulting access violation intermittent (research/s8-renderthread-av-diagnosis.md candidate	// B). The pointers go in as uintptr_t because CRenderPassBase::IsDirty() serialises its tuple	// and static_asserts on non-pointer trivial types.	const uintptr_t hSourceDevTex    = reinterpret_cast<uintptr_t>(pSource->GetDevTexture());	const uintptr_t hDepthDevTex     = reinterpret_cast<uintptr_t>(pDepth->GetDevTexture());	const uintptr_t hHistogramDevTex = reinterpret_cast<uintptr_t>(m_pTexMeterHistogram->GetDevTexture());	if (pass.IsDirty(pSource->GetTextureID(), pDepth->GetTextureID(), m_pTexMeterHistogram->GetTextureID(),	                 hSourceDevTex, hDepthDevTex, hHistogramDevTex))	{		static CCryNameTSCRC techHistogram("SceneReferredMeterHistogram");		pass.SetTechnique(CShaderMan::s_shHDRPostProcess, techHistogram, 0);		pass.SetTexture(0, pSource);		pass.SetTexture(1, pDepth);		pass.SetOutputUAV(0, m_pTexMeterHistogram.get(), m_meterHistogramUAV);	}	pass.BeginConstantUpdate();	{		static CCryNameR paramsName("MeterHistParams");		static CCryNameR weightsName("MeterHistWeights");		pass.SetConstant(paramsName, Vec4((float)width, (float)height, (float)nMode, fSkyWeight));		// The luminance weights of the space the source is actually in this frame. A compute pass		// has no per-view constant buffer binding in this renderer, so GetWorkingLuminance() is		// out of reach and the row is passed in whole rather than as the per-view delta.		const Vec3 weights = CRendererResources::GetWorkingLuminanceWeights();		pass.SetConstant(weightsName, Vec4(weights.x, weights.y, weights.z, 0.0f));	}	const int tile = 8; // must match SCENE_METER_HIST_TILE in HDRPostProcess.cfx	pass.SetDispatchSize((width + tile - 1) / tile, (height + tile - 1) / tile, 1);	// UNBIND THE RENDER TARGETS BEFORE THE DISPATCH. This is the line the whole meter hung on.	//	// The pass that ran immediately before this stage is the quarter-res downsample, and its	// render target is pSource - the very texture this dispatch reads. The D3D11 backend never	// unbinds a render target when a pass ends (CDeviceGraphicsCommandInterfaceImpl has no	// EndRenderPassImpl; only the next BeginRenderPass replaces the OM state), so at this point	// pSource is still bound on the output merger. A graphics pass never notices, because its own	// BeginRenderPass re-targets the OM before its SRVs go in. A compute pass has no render target	// and re-targets nothing, so CSSetShaderResources() is issued with an SRV of a resource that is	// still bound as an RTV - and the D3D11 runtime resolves that hazard by silently filling the	// slot with NULL. The shader then read zeros for every texel: log2(1e-8 / 0.18) is -24 stops,	// which clamps into bin 0, so the histogram came back with its FULL weight in the bottom	// saturating bucket, the camera's band reduction correctly refused to act on a bound instead	// of a value, and AUTO held its last EV forever - which, with no EV ever having been measured,	// is Manual. Every metering mode looked identical because every mode was binning black.	//	// The stock pipeline has exactly this problem and exactly this answer: CTiledLightVolumesStage	// and CVolumetricFogStage both call ClearDeviceOutputState() before their compute dispatches,	// and CRenderPassScheduler does the same before every scheduled compute pass ("TODO:	// Workaround"). On D3D12 and Vulkan the call is a no-op and the hazard does not exist.	ClearDeviceOutputState();	pass.PrepareResourcesForUse(GetDeviceObjectFactory().GetCoreCommandList());	{		SScopedComputeCommandList computeCommandList(false);		pass.Execute(computeCommandList, EShaderStage_All);	}	m_nMeterIssuedMode = nMode;	m_fMeterSkyWeightUsed = fSkyWeight;	m_bMeterHistogramValid = true;}void CAutoExposureStage::Execute(){	FUNCTION_PROFILER_RENDERER();	// The metering histogram FIRST, and before the readback below, for two reasons: the source it	// bins is m_pTexHDRTargetScaled[1][0], which the bloom stage overwrites one pass later, and	// UpdateSceneReferredMeterReadback() chooses which of the two meters to download by reading	// m_bMeterHistogramValid - the flag this call sets. Dispatching it after the readback would	// leave the flag one frame stale on the first frame and, worse, would issue the download of a	// target nothing had written this frame.	//	// This call was MISSING from the day the pass landed (353be581), which is why the Metering	// Mode enum had no effect on anything: the compute pass was built, armed and never dispatched,	// so the bins stayed at zero, m_bMeterHistogramValid stayed false, and the camera silently	// metered off the shipped whole-frame log-mean - a meter with no mask and no mode.	ExecuteMeterHistogram();	MeasureLuminance();	AdjustExposure();	UpdateSceneReferredMeterReadback();	// After AdjustExposure(), which is what sets s_ptexCurLumTexture for this frame.	UpdateStockMidGreyReadback();}// S9 - the STOCK path's mid grey (decisions/s9-glare-stock-threshold.md).//// The problem it solves is in CRendererResources::ResolveThreshold: off the scene-referred switch// the HDR target holds RAW scene radiance, so a glare threshold of "4" meant 4 engine units =// 40 000 cd/m2 - an absolute luminance that has nothing to do with how the frame is exposed. What// grows rays was therefore a different set of objects on the two paths, and on neither path did it// follow the aperture. The fix is to read the same stored number as stops above mid grey on both,// and mid grey on the stock path is the scene value the frame's own exposure puts on 0.18:////     midGrey_raw = 0.18 / fExposure//// fExposure is not a constant the CPU has. It is computed in the tone-mapping shader from the 1x1// ADAPTED luminance texture (FilmMapping, HDRPostProcess.cfx), so this reads that texture back and// evaluates the same formula here. A CPU replica of ComputeExposure() / the Krawczyk branch already// exists in CToneMappingStage::DisplayDebugInfo() for the r_HDRDebug overlay; this is the second,// and both have to be kept in step with the shader by hand - which is why the branch below tests// exactly the cvar the shader's %_RT_SAMPLE4 permutation tests.//// Two or three frames of lag, and it does not matter: what is being read is the output of an// exponential eye-adaptation filter whose time constant (r_HDREyeAdaptationSpeed) is measured in// tenths of a second. A threshold that trails the exposure by two frames cannot be seen; a// threshold that ignores the exposure entirely is what this replaces.//// The whole thing is demand-driven. Nothing on the stock path calls ResolveThreshold unless one of// our own effects is gathering parameters, so with no cinematic camera on the bus the target below// is released and not one byte is allocated or copied.void CAutoExposureStage::UpdateStockMidGreyReadback(){	const bool bCubemapGen = (m_graphicsPipeline.GetRenderFlags() & SHDF_CUBEMAPGEN) != 0;	// Scene-referred: mid grey is 0.18 in the buffer by construction and ResolveThreshold never	// asks. Cube-map generation renders at unity exposure and is not a picture anybody grades.	const bool bWanted = !bCubemapGen	                     && !CRendererResources::IsSceneReferredStage(5)	                     && CRendererResources::IsStockMidGreyDemanded();	if (!bWanted)	{		// Do not free while a download is still in flight - the staging resource is the target of		// a GPU copy that has not necessarily retired.		if (!m_bStockLumReadbackIssued)		{			m_pTexStockLumReadback.reset();			m_bStockLumReadbackStalled = false;		}		CRendererResources::PublishStockMidGrey(0.0f);		return;	}	CTexture* pLumTex = CRendererResources::s_ptexCurLumTexture;	if (!CTexture::IsTextureExist(pLumTex))		return;	if (!CTexture::IsTextureExist(m_pTexStockLumReadback))	{		if (m_bStockLumReadbackIssued)			return;		// FT_STAGE_READBACK is what gives the texture a PERSISTENT staging resource, and that is		// what makes the download two-phase (issue now, map later) instead of a full pipeline		// stall. R16G16F, the same format as the adapted-luminance texture, so the blit is a copy		// and not a conversion.		const uint32 flags = FT_NOMIPS | FT_DONT_STREAM | FT_USAGE_RENDERTARGET | FT_STAGE_READBACK;		const std::string id = m_graphicsPipeline.GetUniqueIdentifierName();		m_pTexStockLumReadback = CTexture::GetOrCreateRenderTarget(("$StockMidGreyReadback" + id).c_str(),		                                                           1, 1, Clr_Transparent, eTT_2D, flags, eTF_R16G16F);		if (!CTexture::IsTextureExist(m_pTexStockLumReadback))		{			m_pTexStockLumReadback.reset();			CryLogAlways("[SceneReferred] stock mid grey: could not create the 1x1 staging target - "			             "the glare thresholds stay ABSOLUTE on the stock path");			return;		}		CryLog("[SceneReferred] stock mid grey armed: the glare family's thresholds are now stops above "		       "the frame's own mid grey on the stock path too (0.18 / the tone map's exposure)");	}	CDeviceTexture* pDevTex = m_pTexStockLumReadback->GetDevTexture();	if (pDevTex == nullptr)		return;	const float fNow = gEnv->pTimer->GetAsyncCurTime();	if (m_bStockLumReadbackIssued)	{		// Not signalled yet: come back next frame. Never block.		if (!pDevTex->AccessCurrStagingResource(0, false))		{			if ((fNow - m_fStockLumIssuedTime) > 5.0f && !m_bStockLumReadbackStalled)			{				m_bStockLumReadbackStalled = true;				CryLogAlways("[SceneReferred] stock mid grey: the staging download has not signalled in 5 s - "				             "the glare thresholds are holding their last value");			}			return;		}		m_bStockLumReadbackStalled = false;		float fAdaptedLum = 0.0f, fAdaptedIllum = 0.0f;		const auto readbackData = [&fAdaptedLum, &fAdaptedIllum](void* pData, uint32 rowPitch, uint32 slicePitch) -> bool		{			// R16G16F: .x is the adapted geometric-mean luminance, .y the adapted illuminance			// estimate. The tone map uses .y in mode 1 and .x in mode 2 - exactly as below.			const CryHalf* pDataHalf = static_cast<const CryHalf*>(pData);			fAdaptedLum   = CryConvertHalfToFloat(pDataHalf[0]);			fAdaptedIllum = CryConvertHalfToFloat(pDataHalf[1]);			return true;		};		pDevTex->AccessCurrStagingResource(0, false, readbackData);		m_bStockLumReadbackIssued = false;		Vec4 hdrSetupParams[5];		gEnv->p3DEngine->GetHDRSetupParams(hdrSetupParams);		float fExposure = 0.0f;		if (CRenderer::CV_r_HDREyeAdaptationMode == 2)		{			// The legacy Krawczyk branch (%_RT_SAMPLE4 in HDRFinalPass, set by CToneMappingStage			// under exactly this test). It is the ENGINE DEFAULT, so it is the branch that matters			// most here. .y/.z of hdrSetupParams[4] are min and max EXPOSURE, not an EV window.			const float fLum = max(fAdaptedLum, 1e-9f);			const float fSceneKey = 1.03f - 2.0f / (2.0f + logf(fLum + 1.0f) / logf(2.0f));			fExposure = clamp_tpl(fSceneKey / fLum, hdrSetupParams[4].y, hdrSetupParams[4].z);		}		else		{			// ComputeExposure(), verbatim, with hdrSetupParams[3] = (EV min, EV max, EV auto			// compensation) - the constant CToneMappingStage binds as HDREyeAdaptation in mode 1.			const float fIllum = max(fAdaptedIllum, 1e-9f);			float fEV100 = logf(fIllum * RENDERER_LIGHT_UNIT_SCALE * 100.0f / 330.0f) / logf(2.0f);			fEV100 -= ((clamp_tpl(log10f(fIllum * RENDERER_LIGHT_UNIT_SCALE + 1.0f), 0.1f, 5.2f) - 3.0f) / 2.0f) * hdrSetupParams[3].z;			fEV100 = clamp_tpl(fEV100, hdrSetupParams[3].x, hdrSetupParams[3].y);			fExposure = (RENDERER_LIGHT_UNIT_SCALE / 1.2f) / powf(2.0f, fEV100);		}		// The one line this function exists for. The vignette in FilmMapping is spatial and is not		// part of it: mid grey is defined at the centre of the frame, where the vignette is 1.		CRendererResources::PublishStockMidGrey((fExposure > 1e-12f)		                                        ? (CRendererResources::kSceneReferredMidGrey / fExposure)		                                        : 0.0f);		return;	}	// Every frame, not on a cadence: this is a threshold the picture is judged against, and a	// once-a-second update would step visibly through a pan from shade into sun.	m_passStockLumCopy.Execute(pLumTex, m_pTexStockLumReadback);	pDevTex->DownloadToStagingResource(0);	m_bStockLumReadbackIssued = true;	m_fStockLumIssuedTime = fNow;}